const fresh=()=>({schemaVersion:1,projectId:crypto.randomUUID(),stateToken:crypto.randomUUID(),consistencyReports:[],assets:[],measurementAnchors:[],measurementChains:[],measurementTolerancePercent:null,name:'Untitled home',revision:'v0',baseSvg:new XMLSerializer().serializeToString(sourceWithIds(demoSVG)),viewBox:[0,0,1000,700],items:[],comments:[],changeLog:[],nextId:1,note:'',calibration:null,photos:[],original:null,objectSettings:{},drawingStyle:{color:'#e55f39',width:4},layers:{base:true,furniture:true,markup:true,comments:true,photos:true}});
