function renderPhotoInspector(){const p=state.photos.find(p=>p.id===photoSelected);$('photo-controls').hidden=!p||!state.layers.photos;const preview=$('photo-preview');preview.removeAttribute('src');if(!p)return;for(const control of $('photo-controls').querySelectorAll('input,textarea,button'))control.disabled=isLocked('photo:'+p.id);photoLoad(p.assetKey).then(data=>{if(photoSelected===p.id&&data)preview.src=data;}).catch(e=>notify(e.message));$('photo-name').textContent=p.name;for(const k of ['x','y','angle','fov','range'])$('photo-'+k).value=p[k]===null?'':p[k];$('photo-note').value=p.note||'';}
function photoPointerDown(e,p){const action=e.target.closest('[data-photo-action]'),g=e.target.closest('[data-photo-id]');if(action&&g&&tool==='select'){selectRef('photo:'+g.dataset.photoId,e,true);if(isLocked('photo:'+g.dataset.photoId)||e.metaKey||e.ctrlKey||e.shiftKey)return true;photoSelected=g.dataset.photoId;selected=photoSelected;const photo=state.photos.find(v=>v.id===photoSelected);active={type:action.dataset.photoAction==='rotate'?'photoRotate':'photoMove',id:photoSelected,p,original:clone(photo),changed:false};$('drawing').setPointerCapture(e.pointerId);render();return true;}if(photoMode){const photo=state.photos.find(v=>v.id===photoSelected);if(!photo)return true;if(isLocked('photo:'+photo.id)){notify('Photo reference is locked.');return true;}active={type:'photoPlace',id:photo.id,p,original:clone(photo),changed:true};photo.x=round(p.x);photo.y=round(p.y);$('drawing').setPointerCapture(e.pointerId);renderPhotos();return true;}return false;}
