function baseEntries(svg=state.baseSvg){if(baseEntryCache?.svg===svg)return baseEntryCache;const doc=sourceWithIds(svg),entries=[];const seen=new Set();for(const node of editableNodes(doc)){const composite=node.closest('[data-dimension-value]'),e=composite||node;if(seen.has(e))continue;seen.add(e);let category='Other shapes';const ancestry=[e,...parentsOf(e)],classes=ancestry.map(n=>n.getAttribute('class')||'').join(' ').split(/\s+/);if(composite)category='Dimensions';else if(classes.some(c=>['annotation','notePin','pending'].includes(c)))category='Source annotations';else if(e.localName==='text')category='Labels';else if(classes.some(c=>['wall','partition'].includes(c)))category='Walls';else if(classes.includes('glass'))category='Windows';else if(e.getAttribute('data-kind')==='opening'||classes.some(c=>['door','slider','jamb'].includes(c)))category='Doors / openings';else if(classes.some(c=>['fixed','kitchen','service'].includes(c)))category='Fixed equipment';else if(classes.some(c=>['room','terrace'].includes(c)))category='Floors / zones';const name=composite?'Dimension '+composite.getAttribute('data-dimension-value')+' '+(composite.getAttribute('data-unit')||''):e.localName==='text'?e.textContent.trim().slice(0,80):e.id;entries.push({ref:'base:'+e.id,id:e.id,kind:'base',category,name,node:e,protected:!!composite||!!e.closest('#dimensions')});}baseEntryCache={svg,doc,entries};return baseEntryCache;}
