function renderBaseHits(){const layer=$('base-hit-layer');layer.replaceChildren();if(tool!=='select'||!state.layers.base||landmarkMatch)return;const {doc,entries}=baseEntries(),root=doc.documentElement.cloneNode(true),vb=parseVB(state.baseSvg);root.setAttribute('x',vb[0]);root.setAttribute('y',vb[1]);root.setAttribute('width',vb[2]);root.setAttribute('height',vb[3]);root.querySelectorAll('style,defs,title,desc').forEach(e=>e.remove());for(const entry of entries){const node=[...root.querySelectorAll('[id]')].find(e=>e.id===entry.id);if(!node)continue;node.dataset.objectRef=entry.ref;if(node.localName==='rect'&&Number(node.getAttribute('width'))>=vb[2]&&Number(node.getAttribute('height'))>=vb[3])node.dataset.noHit='true';if(!sourceElementVisible(entry.node))node.setAttribute('display','none');}for(const node of [root,...root.querySelectorAll('*')]){const strokeOnly=node.localName==='line'||node.getAttribute('fill')==='none'||/(^|\s)(wall|glass|door|thin|dim|partition|jamb|slider|pending)(\s|$)/.test(node.getAttribute('class')||'');node.removeAttribute('id');node.removeAttribute('class');node.removeAttribute('style');if(['path','rect','line','polyline','polygon','circle','ellipse','text'].includes(node.localName)){node.setAttribute('fill','transparent');node.setAttribute('stroke','transparent');node.setAttribute('stroke-width',Math.max(10,Number(node.getAttribute('stroke-width'))||0));node.setAttribute('pointer-events',node.dataset.noHit?'none':strokeOnly?'stroke':'all');}}layer.append(root);}
