function wireCommentReview(){$('cancel-comment').onclick=()=>{$('comment-dialog').close('cancel');};$('comment-dialog').addEventListener('cancel',()=>{commentPoint=null;});$('comment-filter').onchange=renderComments;$('close-review-comment').onclick=()=>$('review-comment-dialog').close();$('complete-comment').onclick=()=>{const summary=$('comment-resolution').value.trim();if(!summary){$('review-comment-status').textContent='Describe the completed change before recording it.';return;}const applied=mutate(()=>{const entry=recordChange('comment-resolved',summary,[reviewedComment]);resolveComments([reviewedComment],entry);});if(!applied)return;$('review-comment-dialog').close();notify('Completed change recorded; comment is gray.');};$('reopen-comment').onclick=()=>{const applied=mutate(()=>{const c=state.comments.find(c=>c.id===reviewedComment),entry=recordChange('comment-reopened','Reopened comment #'+c.n,[c.id]);c.status='open';c.history=c.history||[];c.history.push({status:'open',revision:entry.revision,recordedAt:entry.recordedAt,summary:entry.summary});});if(!applied)return;$('review-comment-dialog').close();notify('Comment reopened; prior resolution retained in history.');};$('show-change-log').onclick=()=>{renderChangeLog();$('change-log-dialog').showModal();};$('close-change-log').onclick=()=>$('change-log-dialog').close();}
