function pointerMove(e){if(!active)return;const p=getPt(e);if(active.type==='originalMove'){active.changed=true;state.original.x=round(active.original.x+p.x-active.p.x);state.original.y=round(active.original.y+p.y-active.p.y);renderOriginal();return;}if(photoPointerMove(e,p))return;if(active.type==='paint'){const point=[round(p.x-active.x),round(p.y-active.y)],last=active.points.at(-1);if(Math.hypot(point[0]-last[0],point[1]-last[1])>=1&&active.points.length<6000)active.points.push(point);$('preview-layer').replaceChildren(paintNode(active));return;}if(active.type==='move'){const dx=p.x-active.p.x,dy=p.y-active.p.y;if(Math.abs(dx)+Math.abs(dy)<.5)return;active.changed=true;const o=state.items.find(z=>z.id===active.id);if(!o)return;o.x=round(active.original.x+dx);o.y=round(active.original.y+dy);if(o.kind==='arrow'){o.x2=round(active.original.x2+dx);o.y2=round(active.original.y2+dy);}renderObjects();renderItemHighlights();}else{active.p=p;const layer=$('preview-layer');layer.replaceChildren();const x=Math.min(active.start.x,p.x),y=Math.min(active.start.y,p.y),w=Math.abs(p.x-active.start.x),h=Math.abs(p.y-active.start.y);if(tool==='arrow')layer.append(make('line',{x1:active.start.x,y1:active.start.y,x2:p.x,y2:p.y,stroke:active.color,'stroke-width':3,'marker-end':'url(#arrowhead)'}));else svgRect(layer,x,y,w,h,{fill:'rgba(229,95,57,.09)',stroke:active.color,'stroke-width':2,'stroke-dasharray':'6 3'});}}
