async function exportSvg(){cancelLandmarkMatch();const expected=JSON.stringify(state);if(state.original&&state.layers.original!==false){const image=$('original-layer').querySelector('image');const data=await photoLoad(state.original.rasterKey);if(JSON.stringify(state)!==expected){notify('Project changed during export. Retry.');return;}if(!image||!data){notify('Original preview is not ready. Retry after loading.');return;}image.setAttribute('href',data);}const cp=$('drawing').cloneNode(true);cp.setAttribute('viewBox',state.viewBox.join(' '));cp.querySelector('#preview-layer')?.remove();cp.querySelector('#base-hit-layer')?.remove();cp.querySelector('#selection-layer')?.remove();const svg=new XMLSerializer().serializeToString(cp);download('annotated-floor-plan.svg',new Blob([svg],{type:'image/svg+xml'}));notify('SVG exported.');}
