function reviewContext(){return {projectId:state.projectId,stateToken:state.stateToken,revision:state.revision,sourceHash:sourceHash(state.baseSvg)};}
function showSavedReview(){
 const runs=state.consistencyReports||[],index=Number($('saved-review').value),r=runs[index];if(!r)return;
 const stale=ConsistencyReview.isStale(r,reviewContext());$('review-status').textContent=r.revision+' · '+r.runAt+' · '+r.status.toUpperCase()+(stale?' · STALE — rerun for current state':' · Current state');
 $('check-results').textContent=r.coverage.map(c=>c.status.toUpperCase()+' · '+({'schematic-geometry':'Schematic geometry','dimension-line-scale':'Dimension annotation scale','anchored-dimension-chains':'Selected endpoint spans','dimension-chain-totals':'Selected dimension-chain totals','rooms-openings-doors':'Rooms, openings and doors','source-notation':'Source notation','as-built-survey':'Physical survey','structural-regulatory':'Structural and regulatory review'}[c.id]||c.id)+' — '+c.detail).join('\n\n')+'\n\n'+r.findings.filter(f=>f.expected!==null).map(f=>f.code+': measured '+f.measured+'; expected '+f.expected+' '+(f.unit||'')).join('\n');
 const comparison=index>0?ConsistencyReview.compareReports(runs[index-1],r):null;$('review-comparison').textContent=comparison?'Compared with previous saved run: '+comparison.added.length+' added, '+comparison.removed.length+' removed, '+comparison.changed.length+' changed, '+comparison.unchanged.length+' unchanged. Removed findings are not proof of a correction if coverage or source changed.':'First saved run; no earlier comparison.';
 const list=$('review-findings');list.replaceChildren();if(!r.findings.length)list.textContent='No findings from the supported schematic checks. See unchecked coverage below.';
 const entries=inventory();for(const finding of r.findings){const row=document.createElement('div'),text=document.createElement('span');text.textContent=finding.status.toUpperCase()+' · '+(finding.code.startsWith('anchor:')?'Source-anchored span':finding.code.startsWith('chain:')?'Source dimension-chain total':finding.code)+(finding.affectedIds.length?' · '+finding.affectedIds.join(', '):'')+(finding.expected!==null?' · measured '+(finding.measured===null?'unavailable':finding.measured)+'; declared '+finding.expected+' '+(finding.unit||''):'')+(finding.code==='review-incomplete'?' — '+finding.evidence.join(' · '):'');row.append(text);if(finding.evidence.length){const details=document.createElement('details'),summary=document.createElement('summary'),pre=document.createElement('pre');summary.textContent='Source evidence and limitations';pre.textContent=finding.evidence.join('\n');details.append(summary,pre);row.append(details);}const refs=finding.affectedIds.map(id=>entries.find(e=>e.id===id||e.kind==='base'&&id.startsWith(e.id+':'))?.ref).filter(Boolean);if(refs.length){const button=document.createElement('button');button.className='button mini';button.textContent='Highlight';button.disabled=stale;button.onclick=()=>{if(ConsistencyReview.isStale(r,reviewContext())){showSavedReview();return;}selectedRefs=new Set(refs);selected=null;render();$('check-dialog').close();$('layer-items').open=true;};row.append(button);}list.append(row);}
}
