function setAssetActivityDraft(maintenance,issues){assertAssetContext(assetExpected);const current=(state.assets||[]).find(a=>a.id===editingAssetId)||AssetRecords.createRecord({id:'asset-draft',projectId:state.projectId,name:'New asset'});const next=AssetRecords.updateActivity(current,{maintenance,issues});assetDraftMaintenance=next.maintenance;assetDraftIssues=next.issues;assetActivityDirty=true;renderAssetActivity();assetNotice('');}
